const req = $input.first().json || {};
const headers = req.headers || {};
const body = req.body || {};
const query = req.query || {};

// 1. Extract Token from Authorization header (Bearer <token>) or body/query
let rawHeader = headers['authorization'] || headers['Authorization'] || '';
let token = '';

if (typeof rawHeader === 'string' && rawHeader.toLowerCase().startsWith('bearer ')) {
  token = rawHeader.substring(7).trim();
} else if (typeof rawHeader === 'string' && rawHeader.trim().length > 0 && !rawHeader.includes(' ')) {
  token = rawHeader.trim();
} else if (body.token) {
  token = String(body.token).trim();
} else if (query.token) {
  token = String(query.token).trim();
}

if (!token) {
  return [{
    json: {
      hasToken: false,
      statusCode: 401,
      error: "Access denied. Authentication token required. Outsiders are not permitted."
    }
  }];
}

return [{
  json: {
    hasToken: true,
    token: token
  }
}];

const inputData = $input.first().json || {};

if (inputData.error) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: "Invalid or expired authentication token. Outsiders are not permitted."
    }
  }];
}

const claims = inputData.payload || inputData;

if (!claims || !claims.sub) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: "Invalid or malformed authentication token. Please log in again."
    }
  }];
}

const callerId = String(claims.sub).trim();
const callerRole = String(claims.role || 'EMPLOYEE').toUpperCase().trim();

const webhookItem = $('Webhook - POST /profile-management').first() || {};
const rawBody = webhookItem.json ? (webhookItem.json.body || webhookItem.json) : {};
const binary = webhookItem.binary || {};

let body = rawBody;
if (typeof rawBody === 'string') {
  try {
    body = JSON.parse(rawBody);
  } catch (e) {
    body = {};
  }
}

const action = String(body.action || 'GET_PROFILE').toUpperCase().trim();
const notifId = 'notif-' + Date.now() + '-' + callerId;

// -------------------------------------------------------------
// 1. ACTION: CHANGE_PASSWORD
// -------------------------------------------------------------
if (action === 'CHANGE_PASSWORD') {
  const oldPass = String(body.oldPassword || '').trim();
  const newPass = String(body.newPassword || '').trim();

  if (!oldPass || !newPass) {
    return [{
      json: {
        valid: false,
        statusCode: 400,
        error: "Both current password and new password are required."
      }
    }];
  }

  if (newPass.length < 6) {
    return [{
      json: {
        valid: false,
        statusCode: 400,
        error: "New password must be at least 6 characters long."
      }
    }];
  }

  const escapedOldPass = oldPass.replace(/'/g, "''");
  const escapedNewPass = newPass.replace(/'/g, "''");

  const sql = `
    WITH auth_check AS (
      SELECT 
        id, 
        (password_hash = crypt('${escapedOldPass}', password_hash) OR password_hash = '${escapedOldPass}') AS is_valid
      FROM employees
      WHERE id = '${callerId}'
    ),
    upd AS (
      UPDATE employees
      SET 
        password_hash = crypt('${escapedNewPass}', gen_salt('bf', 8)),
        updated_at = CURRENT_TIMESTAMP
      WHERE id = '${callerId}'
        AND (SELECT is_valid FROM auth_check) = TRUE
      RETURNING id, email, first_name, last_name, updated_at::TEXT
    ),
    ins_notif AS (
      INSERT INTO notifications (
        id, employee_id, category, title, message, action_route, priority, is_read
      )
      SELECT 
        '${notifId}',
        '${callerId}',
        'COMPANY_ANNOUNCEMENT',
        'Password Changed Successfully',
        'Your account password was updated. If you did not perform this change, contact company operations immediately.',
        '/(tabs)/profile',
        'HIGH',
        FALSE
      FROM upd
      RETURNING id
    )
    SELECT 
      'CHANGE_PASSWORD' AS action_performed,
      (SELECT is_valid FROM auth_check) AS is_old_password_correct,
      row_to_json(upd.*) AS updated_employee
    FROM (SELECT 1) dummy
    LEFT JOIN upd ON true;
  `;

  return [{
    json: {
      valid: true,
      action: 'CHANGE_PASSWORD',
      sqlQuery: sql
    }
  }];
}

// -------------------------------------------------------------
// Extract Avatar Base64 or Multipart Binary
// -------------------------------------------------------------
let avatarBase64 = null;
const binaryKeys = Object.keys(binary);
if (binaryKeys.length > 0) {
  const fileKey = binaryKeys[0];
  const binaryFile = binary[fileKey];
  if (binaryFile && binaryFile.data) {
    const mime = binaryFile.mimeType || 'image/jpeg';
    avatarBase64 = `data:${mime};base64,${binaryFile.data}`;
  }
}

if (!avatarBase64) {
  const rawImg = body.avatar || body.avatarBase64 || body.imageBase64 || body.image || body.avatarUrl || null;
  if (rawImg && typeof rawImg === 'string' && rawImg.trim().length > 0) {
    const trimmed = rawImg.trim();
    if (trimmed.startsWith('data:image/') || trimmed.startsWith('http://') || trimmed.startsWith('https://')) {
      avatarBase64 = trimmed;
    } else {
      avatarBase64 = `data:image/jpeg;base64,${trimmed}`;
    }
  }
}

// -------------------------------------------------------------
// 2. ACTION: UPDATE_AVATAR
// -------------------------------------------------------------
if (action === 'UPDATE_AVATAR') {
  if (!avatarBase64) {
    return [{
      json: {
        valid: false,
        statusCode: 400,
        error: "No image provided. Please provide image binary or base64 string."
      }
    }];
  }

  const escapedAvatar = avatarBase64.replace(/'/g, "''");

  const sql = `
    WITH upd AS (
      UPDATE employees
      SET 
        avatar_url = '${escapedAvatar}',
        updated_at = CURRENT_TIMESTAMP
      WHERE id = '${callerId}'
      RETURNING 
        id, first_name, last_name, email, phone, avatar_url, 
        designation, joining_date::TEXT, employment_type, work_location, role, is_active
    ),
    ins_notif AS (
      INSERT INTO notifications (
        id, employee_id, category, title, message, action_route, priority, is_read
      )
      SELECT 
        '${notifId}',
        '${callerId}',
        'COMPANY_ANNOUNCEMENT',
        'Profile Photo Updated',
        'Your profile avatar was successfully updated.',
        '/(tabs)/profile',
        'NORMAL',
        FALSE
      FROM upd
      RETURNING id
    )
    SELECT 
      'UPDATE_AVATAR' AS action_performed,
      row_to_json(upd.*) AS employee 
    FROM upd;
  `;

  return [{
    json: {
      valid: true,
      action: 'UPDATE_AVATAR',
      sqlQuery: sql
    }
  }];
}

// -------------------------------------------------------------
// 3. ACTION: UPDATE_PROFILE
// -------------------------------------------------------------
if (action === 'UPDATE_PROFILE') {
  const phone = body.phone ? String(body.phone).trim() : null;
  const escapedPhone = phone ? phone.replace(/'/g, "''") : null;
  const escapedAvatar = avatarBase64 ? avatarBase64.replace(/'/g, "''") : null;

  const sql = `
    WITH upd AS (
      UPDATE employees
      SET 
        phone = COALESCE(NULLIF('${escapedPhone || ''}', ''), phone),
        avatar_url = COALESCE(NULLIF('${escapedAvatar || ''}', ''), avatar_url),
        updated_at = CURRENT_TIMESTAMP
      WHERE id = '${callerId}'
      RETURNING 
        id, first_name, last_name, email, phone, avatar_url, 
        designation, joining_date::TEXT, employment_type, work_location, role, is_active
    )
    SELECT 
      'UPDATE_PROFILE' AS action_performed,
      row_to_json(upd.*) AS employee 
    FROM upd;
  `;

  return [{
    json: {
      valid: true,
      action: 'UPDATE_PROFILE',
      sqlQuery: sql
    }
  }];
}

// -------------------------------------------------------------
// 4. ACTION: GET_PROFILE (Default)
// -------------------------------------------------------------
const sql = `
  SELECT 
    'GET_PROFILE' AS action_performed,
    row_to_json(e.*) AS employee
  FROM (
    SELECT 
      id, first_name, last_name, email, phone, avatar_url, 
      designation, joining_date::TEXT, employment_type, work_location, role, is_active
    FROM employees
    WHERE id = '${callerId}'
    LIMIT 1
  ) e;
`;

return [{
  json: {
    valid: true,
    action: 'GET_PROFILE',
    sqlQuery: sql
  }
}];

const items = $input.all();
const data = (items.length > 0 && items[0].json) ? items[0].json : {};
const action = data.action_performed || 'GET_PROFILE';

// 1. Password Change Response
if (action === 'CHANGE_PASSWORD') {
  if (data.is_old_password_correct !== true) {
    return [{
      json: {
        success: false,
        statusCode: 400,
        error: "Current password is incorrect. Please verify your password and try again."
      }
    }];
  }

  if (!data.updated_employee) {
    return [{
      json: {
        success: false,
        statusCode: 500,
        error: "Failed to update password in database."
      }
    }];
  }

  return [{
    json: {
      success: true,
      statusCode: 200,
      message: "Password changed successfully. Your new credentials are now active.",
      updatedAt: data.updated_employee.updated_at
    }
  }];
}

// 2. Profile / Avatar Response
const emp = data.employee;

if (!emp || !emp.id) {
  return [{
    json: {
      success: false,
      statusCode: 404,
      error: "Employee record not found or update failed."
    }
  }];
}

const message = (action === 'UPDATE_AVATAR')
  ? "Profile photo updated successfully."
  : (action === 'UPDATE_PROFILE' ? "Profile updated successfully." : "Profile retrieved successfully.");

return [{
  json: {
    success: true,
    statusCode: 200,
    message: message,
    employee: {
      id: emp.id,
      firstName: emp.first_name,
      lastName: emp.last_name,
      email: emp.email,
      phone: emp.phone,
      avatarUrl: emp.avatar_url || null,
      designation: emp.designation,
      joiningDate: typeof emp.joining_date === 'string' ? emp.joining_date.split('T')[0] : emp.joining_date,
      employmentType: emp.employment_type || 'Full-time',
      workLocation: emp.work_location || 'Chinar Park, Teghoria, Kolkata (In-Office)',
      role: emp.role || 'EMPLOYEE',
      isActive: emp.is_active
    }
  }
}];

